class Solution {
    public int minFlips(int a,int b,int c){
        int answer=0;
        while(a!=0||b!=0||c!=0){
            int bitA=a&1,bitB=b&1,bitC=c&1;
            if(bitC==1){
                if((bitA|bitB)==0)answer++;
            }else answer+=bitA+bitB;
            a>>>=1;
            b>>>=1;
            c>>>=1;
        }
        return answer;
    }
}

